mapper.select:
SELECT ps.id AS skuId, ps.specs AS skuName, p.id AS productId, p.name AS productName, SUM(oi.qty) AS qty, SUM(oi.price * oi.qty) AS amount FROM orders o JOIN order_items oi ON oi.order_id = o.id JOIN product_skus ps ON ps.id = oi.sku_id JOIN products p ON p.id = ps.product_id WHERE o.status IN
AND o.created_at >= CONCAT(#{startDate}, ' 00:00:00') AND o.created_at < DATE_ADD(CONCAT(#{endDate}, ' 00:00:00'), INTERVAL 1 DAY)
GROUP BY ps.id, ps.specs, p.id, p.name ORDER BY qty DESC, amount DESC LIMIT #{limit}
